import os, sys, subprocess, shlex

def _read(args):
    level='none'; maxlines=None; tail=None; nums=False; files=[]; i=0
    while i<len(args):
        a=args[i]
        if a in ('-h','--help'):
            print('Read file with intelligent filtering\n\nUsage: executable read [OPTIONS] <FILES>...\n\nOptions:\n  -l, --level <LEVEL>            Filter: none (default, full content), minimal, aggressive [default: none]\n  -m, --max-lines <MAX_LINES>    Max lines\n      --tail-lines <TAIL_LINES>  Keep only last N lines\n  -n, --line-numbers             Show line numbers'); return 0
        if a in ('-l','--level') and i+1<len(args): level=args[i+1]; i+=2; continue
        if a.startswith('--level='): level=a.split('=',1)[1]
        elif a in ('-m','--max-lines') and i+1<len(args): maxlines=int(args[i+1]); i+=2; continue
        elif a.startswith('--max-lines='): maxlines=int(a.split('=',1)[1])
        elif a=='--tail-lines' and i+1<len(args): tail=int(args[i+1]); i+=2; continue
        elif a.startswith('--tail-lines='): tail=int(a.split('=',1)[1])
        elif a in ('-n','--line-numbers'): nums=True
        elif a.startswith('-'): pass
        else: files.append(a)
        i+=1
    rc=0
    for fi,f in enumerate(files):
        try:
            with open(f,encoding='utf-8',errors='replace') as fp: lines=fp.read().splitlines()
        except OSError as e: print(f'rtk: {e}',file=sys.stderr); rc=1; continue
        if len(files)>1: print(f'==> {f} <==')
        if level=='minimal':
            lines=[x for x in lines if x.strip() and not x.lstrip().startswith(('#','//','/*','*'))]
        elif level=='aggressive':
            kept=[]; inbody=False
            for line in lines:
                s=line.strip()
                if s.startswith(('def ','class ','async def ','function ','export function ','export const ','pub fn ','fn ','const ','let ','interface ','type ')):
                    kept.append(line); inbody=False
                elif s and not line[:1].isspace(): kept.append(line)
                elif s and not inbody: kept.append('    // ... implementation'); inbody=True
            lines=kept
        if tail is not None: lines=lines[-tail:]
        if maxlines is not None and len(lines)>maxlines: lines=lines[:maxlines]+[f'... ({len(lines)-maxlines} more lines)']
        for n,line in enumerate(lines,1): print(f'{n} │ {line}' if nums else line)
    return rc

def _ls(args):
    opts=[]; paths=[]; i=0
    while i<len(args):
        a=args[i]
        if a in ('-h','--help'):
            print('List directory contents with token-optimized output (proxy to native ls)\n\nUsage: executable ls [OPTIONS] [ARGS]...'); return 0
        if a.startswith('-'): opts.append(a)
        else: paths.append(a)
        i+=1
    if any('l' in a[1:] for a in opts):
        return subprocess.run(['ls']+opts+(paths or ['.'])).returncode
    rc=0
    for path in paths or ['.']:
        if len(paths)>1: print(path+':')
        try:
            if os.path.isdir(path):
                names=os.listdir(path)
                if not any('a' in x[1:] for x in opts): names=[n for n in names if not n.startswith('.')]
                dirs=sorted([n for n in names if os.path.isdir(os.path.join(path,n))]); files=sorted(n for n in names if not os.path.isdir(os.path.join(path,n)))
                for n in dirs+files:
                    p=os.path.join(path,n)
                    if os.path.isdir(p): print(n+'/')
                    else:
                        try: print(f'{n}  {os.path.getsize(p)}B')
                        except OSError: print(n)
            else:
                print(os.path.basename(path))
        except OSError as e: print(f'ls: cannot access {path}: {e.strerror}',file=sys.stderr); rc=2
    return rc

def handle(cmd,args):
    if cmd=='read': return True,_read(args)
    if cmd=='ls': return True,_ls(args)
    if cmd=='tree':
        if not shutil_which('tree'):
            print('rtk: tree command not found. Install it first:\n- macOS: brew install tree\n- Ubuntu/Debian: sudo apt install tree\n- Fedora/RHEL: sudo dnf install tree\n- Arch: sudo pacman -S tree',file=sys.stderr); return True,1
        return True,subprocess.run(['tree']+args).returncode
    if cmd=='find': return True,_find(args)
    return False,0

def shutil_which(c):
    from shutil import which
    return which(c)

def _find(args):
    # The native find wrapper emits a compact directory and extension summary.
    roots=[]; opts=[]; i=0
    while i<len(args):
        if args[i].startswith('-'): opts.extend(args[i:]); break
        roots.append(args[i]); i+=1
    if not roots: roots=['.']
    raw=subprocess.run(['find']+roots+opts,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    if raw.stderr: print(raw.stderr,end='',file=sys.stderr)
    if raw.returncode: return raw.returncode
    paths=[p for p in raw.stdout.splitlines() if os.path.isfile(p) or os.path.isdir(p)]
    files=[p for p in paths if os.path.isfile(p)]; dirs=[p for p in paths if os.path.isdir(p)]
    exts={}
    for p in files:
        e=os.path.splitext(p)[1] or '.none'; exts[e]=exts.get(e,0)+1
    print(f'{len(files)}F {len(dirs)}D:\n')
    childdirs=set()
    for d in dirs:
        try: childdirs.update(os.path.join(d,x) for x in os.listdir(d) if os.path.isdir(os.path.join(d,x)))
        except OSError: pass
    for d in dirs:
        try:
            children=sorted(os.listdir(d)); children=[x for x in children if os.path.join(d,x) in paths or not opts]
            print(d.rstrip('/')+'/ '+' '.join(children))
        except OSError: pass
    if exts: print('\next: '+' '.join(f'{e}({exts[e]})' for e in sorted(exts)))
    return 0
import difflib, os, re, sys

def compact_diff(a, b, names=('', '')):
    old=a.splitlines(); new=b.splitlines()
    sm=difflib.SequenceMatcher(a=old,b=new,autojunk=False)
    added=removed=modified=0; rows=[]
    for tag,i,j,k,l in sm.get_opcodes():
        if tag=='equal': continue
        if tag=='replace':
            removed+=j-i; added+=l-k
            for z in range(i,j): rows.append((f"-   {z+1} {old[z]}",None))
            for z in range(k,l): rows.append((f"+   {z+1} {new[z]}",None))
        elif tag=='delete':
            removed+=j-i
            for z in range(i,j): rows.append((f"-   {z+1} {old[z]}",None))
        else:
            added+=l-k
            for z in range(k,l): rows.append((f"+   {z+1} {new[z]}",None))
    out=f"{names[0]} → {names[1]}\n   +{added} added, -{removed} removed, ~{modified} modified"
    for x,y in rows:
        out+='\n\n'+x
        if y: out+='\n'+y
    return out+'\n'

def do_diff(args):
    if not args or args[0] in ('-h','--help'): return 0
    p=args[0]
    try:
        if p=='-': a=sys.stdin.read(); na='stdin'
        else: a=open(p,errors='replace').read(); na=p
        if len(args)>1: q=args[1]; b=open(q,errors='replace').read(); nb=q
        elif p!='-': return 2
        else: b=sys.stdin.read(); nb='stdin'
    except OSError as e: print(e,file=sys.stderr); return 1
    sys.stdout.write(compact_diff(a,b,(na,nb))); return 0

def do_grep(args):
    if not args or args[0] in ('-h','--help'): return 0
    pat=args[0]; path=args[1] if len(args)>1 and not args[1].startswith('-') else '.'
    opts=args[2:] if path!='.' or len(args)>1 and args[1].startswith('-') else args[1:]
    insensitive='-i' in opts or '--ignore-case' in opts
    try: rx=re.compile(pat,re.I if insensitive else 0)
    except re.error as e: print(f"invalid regex: {e}",file=sys.stderr); return 2
    files=[]
    if os.path.isfile(path): files=[path]
    elif os.path.isdir(path):
        for root,dirs,names in os.walk(path):
            dirs[:]=[d for d in dirs if not d.startswith('.')]
            for n in sorted(names): files.append(os.path.join(root,n))
    else: print(f"No such file or directory: {path}",file=sys.stderr); return 2
    matches=[]
    ext=None
    if '-t' in opts:
        try: ext=opts[opts.index('-t')+1].lstrip('.')
        except: pass
    for f in files:
        if ext and not f.endswith('.'+ext): continue
        try:
            for num,line in enumerate(open(f,errors='replace'),1):
                line=line.strip()
                if rx.search(line): matches.append((f,num,line))
        except (OSError,UnicodeError): continue
    limit=200
    for flag in ('--max','-m'):
        if flag in opts:
            try: limit=int(opts[opts.index(flag)+1])
            except: pass
    if not matches: print('No matches found'); return 1
    shown=matches[:limit]; print(f"{len(matches)} matches in {len(set(x[0] for x in matches))} files:\n")
    for f,n,line in shown:
        if len(line)>80: line=line[:77]+'...'
        print(f"{f}:{n}:{line}")
    if len(shown)<len(matches): print(f"... {len(matches)-len(shown)} more matches")
    return 0

"""Command rewriting used by RTK's hook integrations."""
import os
import re
import shlex

# Commands with native filters. More entries are intentionally accepted: the
# reference ships filters for a broad set of developer tools.
SUPPORTED = set('''ls tree read smart git gh glab aws psql pnpm err test json deps env find diff log dotnet docker kubectl summary grep init wget wc gain cc-economics config jest vitest prisma tsc next lint prettier format playwright cargo npm npx curl discover session telemetry learn run proxy pipe trust untrust verify ruff pytest mypy rake rubocop rspec pip go gt golangci-lint gradlew hook-audit rewrite hook terraform make brew composer poetry helm rsync'''.split())

def _rewrite_segment(segment):
    """Rewrite one shell command while retaining its original spelling."""
    # Preserve leading whitespace and shell assignments/prefixes.
    m = re.match(r'^(\s*)((?:[A-Za-z_][A-Za-z0-9_]*=[^\s]+\s+)*)(.*)$', segment, re.S)
    if not m:
        return segment, False
    lead, envs, body = m.groups()
    if not body.strip():
        return segment, False
    try:
        words = shlex.split(body, posix=True)
    except ValueError:
        return segment, False
    if not words:
        return segment, False
    # Do not rewrite shell builtins, paths, or arbitrary executables.
    cmd = words[0]
    if cmd in ('sudo', 'command', 'time', 'env') and len(words) > 1:
        prefix = cmd + ' '
        sub = ' '.join(words[1:])
        rewritten, ok = _rewrite_segment(sub)
        if ok:
            return lead + envs + prefix + rewritten.strip(), True
        return segment, False
    if '/' in cmd or cmd.startswith('-'):
        return segment, False
    if cmd == 'rtk':
        return segment, True
    aliases = {'cat': 'read', 'rg': 'grep', 'fd': 'find'}
    if cmd in SUPPORTED or cmd in aliases:
        if cmd in aliases:
            target = aliases[cmd]
        else:
            target = cmd
        # `ls` and others are dispatched by rtk; retain arguments verbatim.
        rewritten = target + body[len(cmd):]
        return lead + envs + 'rtk ' + rewritten, True
    return segment, False

def rewrite(command):
    """Return (rewritten command, changed/supported). Compound shell commands
    are rewritten clause by clause, leaving operators and unsupported clauses."""
    if not command.strip():
        return '', False
    if os.environ.get('RTK_DISABLED') == '1':
        return '', False
    # Split on shell control operators outside quotes. The RTK hook deliberately
    # leaves heredocs and complex constructs alone.
    chunks = re.split(r'((?:&&|\|\||;|\|)\s*)', command)
    any_supported = False
    for i in range(0, len(chunks), 2):
        part, ok = _rewrite_segment(chunks[i])
        chunks[i] = part
        any_supported |= ok
    return ''.join(chunks), any_supported
"""Standalone log output compaction used by the RTK-compatible CLI."""
from collections import Counter
import re
import sys

_ERROR = re.compile(r"\b(error|fatal|critical|panic)\b", re.I)
_WARN = re.compile(r"\b(warn(?:ing)?)\b", re.I)
_INFO = re.compile(r"\b(info)\b", re.I)


def compact_log(text: str, ultra: bool = False) -> str:
    errors, warnings, infos = [], [], []
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        if _ERROR.search(s):
            errors.append(s)
        elif _WARN.search(s):
            warnings.append(s)
        elif _INFO.search(s):
            infos.append(s)
    def unique(items):
        counts = Counter(items)
        return [(s, counts[s]) for s in dict.fromkeys(items)]
    e, w = unique(errors), unique(warnings)
    out = ["Log Summary", f"   [error] {len(errors)} errors ({len(e)} unique)",
           f"   [warn] {len(warnings)} warnings ({len(w)} unique)",
           f"   [info] {len(infos)} info messages", ""]
    for title, items in (("ERRORS", e), ("WARNINGS", w)):
        if not items:
            continue
        out.append(f"[{title}]")
        for line, count in items:
            prefix = f"[×{count}] " if count > 1 else ""
            out.append("   " + prefix + line)
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def run_log(path=None, stdin=None, ultra=False):
    try:
        if path:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                data = f.read()
        else:
            data = sys.stdin.read() if stdin is None else stdin
    except OSError as exc:
        print(f"rtk: {exc}", file=sys.stderr)
        return 1
    sys.stdout.write(compact_log(data, ultra))
    return 0

