#!/usr/bin/env python3
import sys,os,subprocess
import envcmd,fsutil,gdiff,logutil,rewrite_util

HELP='''High-performance CLI proxy that filters and summarizes system outputs.

Usage: executable [OPTIONS] <COMMAND>

Commands: ls tree read smart git gh glab aws psql pnpm err test json deps env find diff log dotnet docker kubectl summary grep init wget wc gain config run proxy pipe rewrite help'''

def wc(args):
    flags=[]; files=[]; i=0
    while i<len(args):
        if args[i] in ('-h','--help'): print('Word/line/byte count with compact output (strips paths and padding)\n\nUsage: executable wc [OPTIONS] [ARGS]...'); return 0
        if args[i].startswith('-'): flags.append(args[i])
        else: files.append(args[i])
        i+=1
    data=[]
    if not files: data=[('-',sys.stdin.buffer.read())]
    else:
        for p in files:
            try:data.append((p,open(p,'rb').read()))
            except OSError as e: print(f'wc: {e.strerror}: {p}',file=sys.stderr); return 1
    totals=[0,0,0]
    for p,b in data:
        counts=[b.count(b'\n'),len(b.decode(errors='replace').split()),len(b)]
        totals=[x+y for x,y in zip(totals,counts)]
        if '-l' in flags: ix=[0]
        elif '-w' in flags: ix=[1]
        elif '-c' in flags or '-m' in flags: ix=[2]
        else: ix=[0,1,2]
        print(' '.join(str(counts[j]) for j in ix))
    if len(data)>1:
        ix=[0] if '-l' in flags else [1] if '-w' in flags else [2] if '-c' in flags or '-m' in flags else [0,1,2]
        print(' '.join(str(totals[j]) for j in ix))
    return 0

def main(argv):
    args=list(argv)
    while args and args[0].startswith('-') and args[0] in ('-v','-vv','-vvv','--ultra-compact','--skip-env'): args.pop(0)
    if not args or args[0] in ('-h','--help','help'):
        print(HELP); return 0
    if args[0] in ('-V','--version'): print('rtk 0.42.0'); return 0
    cmd=args.pop(0)
    if cmd in ('ls','tree','read','find'):
