"""Compact structural JSON renderer."""
import json,sys

def _type(v):
    if v is None:return 'null'
    if isinstance(v,bool):return 'bool'
    if isinstance(v,str):return 'string'
    if isinstance(v,int):return 'int'
    if isinstance(v,float):return 'float'
    return 'null'

def render(obj, keys_only=False, depth=5):
    def scalar(v):
        return _type(v) if keys_only else json.dumps(v,ensure_ascii=False,separators=(',',':'))
    def fmt(v,level=0):
        pad='  '*level
        if isinstance(v,dict):
            if level>=depth:return pad+'...'
            if not v:return pad+'{}'
            lines=[pad+'{']
            for k in sorted(v):
                x=v[k]; p='  '*(level+1)
                if isinstance(x,(dict,list)):
                    lines.append(p+str(k)+':')
                    lines.append(fmt(x,level+1))
                else:
                    lines.append(p+str(k)+': '+scalar(x)+(',' if keys_only else ''))
            lines.append(pad+'}')
            return '\n'.join(lines)
        if isinstance(v,list):
            if level>=depth:return pad+'...'
            if not v:return pad+'[]'
            if keys_only and all(not isinstance(x,(dict,list)) for x in v):
                kinds=list(dict.fromkeys(_type(x) for x in v))
                return pad+'['+', '.join(kinds)+f'] ({len(v)})'
            lines=[pad+'[']
            for x in v:
                lines.append(fmt(x,level+1)+',')
            lines.append(pad+']')
            return '\n'.join(lines)
        return pad+scalar(v)
    return fmt(obj)+'\n'

def run(args):
